from zipfile import ZipFile
from lxml import etree
p='documents/turn-2-redline-meridian.docx'
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with ZipFile(p) as z: root=etree.fromstring(z.read('word/document.xml'))
paras=root.xpath('.//w:body//w:p',namespaces=ns)
for i in list(range(20,36))+list(range(60,78))+list(range(100,111))+list(range(225,274))+list(range(280,307)):
    if i>=len(paras): continue
    para=paras[i]
    def text(n): return ''.join(x.text or '' for x in n.xpath('.//w:t|.//w:delText',namespaces=ns))
    print('\nP',i, text(para)[:180])
    for child in para:
      if child.tag.endswith('}pPr'): continue
      if child.tag.endswith('}ins') or child.tag.endswith('}del'):
        print(' ',child.tag.split('}')[-1], child.get('{%s}author'%ns['w']), text(child)[:140])
PY","description":"Inspect targeted tracked-change paragraphs"}

